package main

import (
	"bytes"
	"fmt"
	"io"
	"strings"
)

func copyText(dst io.Writer, src io.Reader) (int64, error) {
	return io.Copy(dst, src)
}

func main() {
	var output bytes.Buffer
	count, err := copyText(&output, strings.NewReader("portable stream"))
	if err != nil {
		panic(err)
	}
	fmt.Println(count, output.String())
}
