package main

import (
	"fmt"
	"io"
)

type finalReader struct{ done bool }

func (r *finalReader) Read(p []byte) (int, error) {
	if r.done {
		return 0, io.EOF
	}
	r.done = true
	return copy(p, "last"), io.EOF
}

func main() {
	reader := &finalReader{}
	buffer := make([]byte, 8)
	result := []byte{}
	for {
		n, err := reader.Read(buffer)
		if n > 0 {
			result = append(result, buffer[:n]...)
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			panic(err)
		}
	}
	fmt.Println(string(result))
}
