package main

import (
	"errors"
	"fmt"
	"io"
)

type brokenWriter struct{}

func (brokenWriter) Write(p []byte) (int, error) {
	return len(p) / 2, nil
}

func writeOnce(w io.Writer, p []byte) error {
	n, err := w.Write(p)
	if err != nil {
		return err
	}
	if n != len(p) {
		return io.ErrShortWrite
	}
	return nil
}

func main() {
	err := writeOnce(brokenWriter{}, []byte("hello"))
	fmt.Println(errors.Is(err, io.ErrShortWrite))
}
